package org.apache.commons.math.optimization;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.random.RandomGenerator;
import org.apache.commons.math.util.LocalizedFormats;
import org.apache.commons.math3.optim.univariate.UnivariateRealFunction;
import org.apache.commons.math3.optim.univariate.UnivariateRealOptimizer;
import org.apache.commons.math3.random.RandomGenerator;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

public class MultiStartUnivariateRealOptimizer_getFunctionValue_TriageGen0Test {

    @Mock
    private UnivariateRealOptimizer mockOptimizer;

    @Mock
    private RandomGenerator mockGenerator;

    private MultiStartUnivariateRealOptimizer multiStartOptimizer;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // Initialize the class under test with mocked dependencies
        multiStartOptimizer = new MultiStartUnivariateRealOptimizer(mockOptimizer, 10, mockGenerator);
    }

    /**
     * Tests that getFunctionValue returns the exact value provided by the underlying optimizer.
     * This covers the primary execution path of the method.
     */
    @Test
    public void testGetFunctionValueReturnsCorrectValue() {
        // Arrange
        double expectedValue = 42.0;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals("The returned function value should match the value from the underlying optimizer.", 
                     expectedValue, actualValue, 1e-15);
    }

    /**
     * Tests that getFunctionValue correctly handles edge cases like zero or negative values.
     */
    @Test
    public void testGetFunctionValueWithZero() {
        // Arrange
        double expectedValue = 0.0;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals(expectedValue, actualValue, 1e-15);
    }

    /**
     * Tests that getFunctionValue handles negative values correctly.
     */
    @Test
    public void testGetFunctionValueWithNegative() {
        // Arrange
        double expectedValue = -123.456;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals(expectedValue, actualValue, 1e-15);
    }

    /**
     * Tests that getFunctionValue handles NaN (Not a Number) if the optimizer returns it.
     */
    @Test
    public void testGetFunctionValueWithNaN() {
        // Arrange
        double expectedValue = Double.NaN;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals(Double.NaN, actualValue);
    }

    /**
     * Tests that getFunctionValue handles Infinity if the optimizer returns it.
     */
    @Test
    public void testGetFunctionValueWithInfinity() {
        // Arrange
        double expectedValue = Double.POSITIVE_INFINITY;
        when(mockOptimizer.getFunctionValue()).thenReturn(expectedValue);

        // Act
        double actualValue = multiStartOptimizer.getFunctionValue();

        // Assert
        assertEquals(Double.POSITIVE_INFINITY, actualValue, 0.0);
    }
}
